    @GetMapping("/appointments/live")
    public org.springframework.web.servlet.ModelAndView liveAppointments(@AuthenticationPrincipal CustomUserDetails user,
            @RequestParam(required=false) Integer maCV,  Model model) {
        appointments(user, maCV, model);
        // A direct View bypasses page decoration and returns only the calendar fragment.
        var view=new org.springframework.web.servlet.view.JstlView("/WEB-INF/jsp/student/appointments-live.jsp");
        view.setAlwaysInclude(true); view.setContentType("text/html;charset=UTF-8");
        return new org.springframework.web.servlet.ModelAndView(view, model.asMap());
    }

    @GetMapping("/appointments")
    public String appointments(@AuthenticationPrincipal CustomUserDetails userDetails, @RequestParam(required = false) Integer maCV, Model model) {
        SinhVien sv = getStudentOrThrow(userDetails);
        var activeAdvisors = catalogService.getAllActiveAdvisors();
        if (maCV == null && !activeAdvisors.isEmpty()) maCV = activeAdvisors.getFirst().getMaCV();
        var studentAppointments = appointmentService.getStudentAppointments(sv.getMaSV());
        model.addAttribute("appointments", studentAppointments);
        model.addAttribute("cancellationBlocks", studentAppointments.stream().collect(Collectors.toMap(
                LichHenTuVan::getMaLichHen, appointmentService::cancellationBlockReason)));
        model.addAttribute("cancellationDeadlines", studentAppointments.stream().collect(Collectors.toMap(
                LichHenTuVan::getMaLichHen, appointmentService::cancellationDeadline)));
        model.addAttribute("availableSlots", appointmentService.getAvailableSlots(maCV));
        model.addAttribute("advisors", activeAdvisors);
        model.addAttribute("selectedCv", maCV);
        model.addAttribute("officeDays", officeRequests.getCalendar(maCV));
        return "student/appointments";
    }

    @PostMapping("/appointments/request")
    public String requestAppointment(@AuthenticationPrincipal CustomUserDetails userDetails,
            @RequestParam Integer maCV,
            @RequestParam @org.springframework.format.annotation.DateTimeFormat(iso=org.springframework.format.annotation.DateTimeFormat.ISO.DATE_TIME) java.time.LocalDateTime start,
            @RequestParam String hinhThuc, @RequestParam String chuDe, @RequestParam String noiDungHen,
            RedirectAttributes flash) {
        try {
            officeRequests.request(getStudentOrThrow(userDetails),maCV,start,hinhThuc,chuDe,noiDungHen);
            flash.addFlashAttribute("successMessage","Đã gửi đề xuất lịch hẹn. Buổi hẹn chỉ được xác nhận khi cố vấn duyệt.");
        } catch(RuntimeException ex) { flash.addFlashAttribute("errorMessage",ex.getMessage()); }
        return "redirect:/student/appointments";
    }

